def parse_charges(text):
    text=str(text).strip()
    mm=re.search(r'\[罪名\](.*?)(?:<eoa>|$)',text)
    if mm: text=mm.group(1).strip()
    elif '罪名:' in text or '罪名：' in text: text=re.split(r'罪名[:：]',text)[-1]
    text=re.sub(r'<eoa>.*','',text).strip()
    for sep in [';','；',',','，','、']:
        if sep in text: return {p.strip() for p in text.split(sep) if p.strip()}
    return {text} if text else set()

