import sys, json, glob, re, importlib.util
sys.path.insert(0,'/tmp/an')
from base import RUNS, parse_charges

FIELD = re.compile(r'("final_answer"\s*:\s*")((?:[^"\\]|\\.)*)(")')

def raw_replies(root, task):
    out=[]
    for f in sorted(glob.glob(root+'/'+task+'/conversations/*/sample-*.json')):
        c=json.load(open(f))
        msgs=c.get('messages') or []
        last=msgs[-1] if msgs else None
        if not last or last['role']!='assistant':
            continue
        content=last.get('content')
        if isinstance(content,list):
            content=''.join(b.get('text','') if isinstance(b,dict) else str(b) for b in content)
        out.append({'file':f,'raw':str(content),'pred':c['prediction'],'target':c['target'],
                    'was':c['was_correct'],'idx':c['example_index'],'s':c['sample_index']})
    return out

def field_text(content):
    """The stretch the middleware rewrites: the final_answer value, or the whole text."""
    text=str(content)
    if not FIELD.search(text):
        return text, None, None
    m=FIELD.search(text)
    return m.group(2), m.group(1), m.group(3)

def apply_rule(raw, space, rule):
    text=str(raw)
    if not FIELD.search(text):
        return rule(text, space)
    return FIELD.sub(lambda f: f"{f.group(1)}{rule(f.group(2), space)}{f.group(3)}", text)

def pred_charges(text):
    return parse_charges(text)
