import sys; sys.path.insert(0,'/tmp/an')
from replay import *

class Space(M.AnswerSpace):
    """AnswerSpace with an overridable variant."""
    def variant(self, unit):
        raise NotImplementedError

def score(space_cls, task='LawBench', verbose=False):
    total=0; base_total=0
    detail={}
    for name,root in RUNS.items():
        sp0,mem=space_for(root,task)
        sp=space_cls(mem)
        rr=raw_replies(root,task)
        c=0; b=0
        for r in rr:
            tgt=parse_charges(r['target'])
            p=parse_charges(apply_rule(r['raw'], sp, lambda t,s: s.respell(t)))
            pb=parse_charges(apply_rule(r['raw'], sp0, lambda t,s: s.respell(t)))
            if p==tgt: c+=1
            if pb==tgt: b+=1
        detail[name]=(c,b,len(rr))
        total+=c; base_total+=b
    return total, base_total, detail

class Cur(Space):
    def variant(self, unit):
        return M.AnswerSpace.variant(self, unit)
