import sys; sys.path.insert(0,'/tmp/an')
from variants import *

def compare(cls, task='LawBench', show=True, limit=200):
    gains=[]; losses=[]; inert=[]
    for name,root in RUNS.items():
        sp0,mem=space_for(root,task)
        sp=cls(mem)
        for r in raw_replies(root,task):
            tgt=parse_charges(r['target'])
            new=parse_charges(apply_rule(r['raw'], sp, lambda t,s: s.respell(t)))
            old=parse_charges(apply_rule(r['raw'], sp0, lambda t,s: s.respell(t)))
            if new==old: continue
            row=(name,r['idx'],r['s'],old,new,tgt,r['raw'][:200])
            if new==tgt and old!=tgt: gains.append(row)
            elif old==tgt and new!=tgt: losses.append(row)
            else: inert.append(row)
    if show:
        print(f'--- {cls.__name__}: gains={len(gains)} losses={len(losses)} other-changes={len(inert)}')
        for kind,rows in (('GAIN',gains),('LOSS',losses),('OTHER',inert)):
            for n,i,s,old,new,tgt,raw in rows[:limit]:
                print(f'  {kind} {n} q{i} s{s}: {sorted(old)} -> {sorted(new)}  tgt={sorted(tgt)}')
    return gains,losses,inert
